sect1.example:
  Manejo de un error Throwable con un bloque &finally;


<?php
function inverse($x) {
    return 1/$x;
}

try {
    echo inverse(5) . "\n";
} catch (\DivisionByZeroError $e) {
    echo 'Error capturado: ', $e->getMessage(), "\n";
} finally {
    echo "Primer finally.\n";
}

try {
    echo inverse(0) . "\n";
} catch (\DivisionByZeroError $e) {
    echo 'Error capturado: ', $e->getMessage(), "\n";
} finally {
    echo "Segundo finally.\n";
}

// Continuar la ejecución
echo "Hola mundo\n";


  &example.outputs.8;


0.2
Primer finally.
Error capturado: Division by zero
Segundo finally.
Hola mundo

  Se ejecutarán todos los bloques &finally;


<?php
try {
    try {
        throw new Exception();
    } finally {
        echo "Finally interno\n";
    }
} catch (Exception $e) {
} finally {
    echo "Finally externo\n";
}


  &example.outputs;


Finally interno
Finally externo

sect2.example:
   Interacción entre &return; en un bloque &finally; y un &return; anterior


<?php
function testReturnTry() {
    try {
        echo 'Dentro de try', "\n";
        return 'try';
    } finally {
        echo 'Dentro de finally', "\n";
        return 'finally';
    }
}

function testReturnCatch() {
    try {
        throw new Exception('foo');
    } catch (Exception $e) {
        echo 'Dentro de catch', "\n";
        return 'catch';
    } finally {
        echo 'Dentro de finally', "\n";
        return 'finally';
    }
}

echo testReturnTry(), "\n";
echo testReturnCatch(), "\n";



   &example.outputs;


Dentro de try
Dentro de finally
finally
Dentro de catch
Dentro de finally
finally

   Interacción entre el bloque &finally; y &return;


<?php
function testReturnTry() {
    try {
        return 'try';
    } finally {
        echo 'finally ';
    }
}

function testReturnCatch() {
    try {
        throw new Exception('foo');
    } catch (Exception $e) {
        return 'catch';
    } finally {
        echo 'finally ';
    }
}

echo testReturnTry(), "\n";
echo testReturnCatch(), "\n";


   &example.outputs;


finally try
finally catch

   Excepción en try y en finally


<?php

try {
    try {
        throw new Exception(message: 'Third', previous: new Exception('Fourth'));
    } finally {
        throw new Exception(message: 'First', previous: new Exception('Second'));
    }
} catch (Exception $e) {
    var_dump(
        $e->getMessage(),
        $e->getPrevious()->getMessage(),
        $e->getPrevious()->getPrevious()->getMessage(),
        $e->getPrevious()->getPrevious()->getPrevious()->getMessage(),
    );
}


   &example.outputs;


string(5) "First"
string(6) "Second"
string(5) "Third"
string(6) "Fourth"


    Bloque &finally; ejecutado cuando se ha lanzado una
    Exception



<?php
function generate()
{
    try {
        yield 1;
        yield 2;
    } catch (\Exception $e) {
        echo 'catch';
    } finally {
        echo "finally\n";
    }
}

try {
    foreach (generate() as $i) {
        echo $i, "\n";
        throw new Exception();
    }
} catch (Exception $e) {
    echo 'catch externo';
}


   &example.outputs.similar;


1
finally
catch externo


    Error al utilizar &yield; en un bloque &finally; cuando se ha lanzado una
    Exception



<?php
function generate()
{
    try {
        yield 1;
        yield 2;
    } catch (\Exception $e) {
        echo 'catch';
    } finally {
        echo "finally\n";
        yield 3;
    }
}

try {
    foreach (generate() as $i) {
        echo $i, "\n";
        throw new Exception();
    }
} catch (Exception $e) {
    echo 'catch externo';
}


   &example.outputs.similar;


